// Note: API-имена Jinx UI (Modal.*, Button variant="danger", Text) взяты по общепринятому соглашению —
// сверься с версией @jinx-ui/react в проекте, если названия отличаются.
import { useCallback, useState } from 'react';
import { Button, Modal, Stack, Text } from '@jinx-ui/react';

type DeleteProjectDialogProps = {
  onConfirm: () => void;
  projectName?: string;
};

export default function DeleteProjectDialog({ onConfirm, projectName }: DeleteProjectDialogProps) {
  const [isOpen, setIsOpen] = useState(false);

  const close = useCallback(() => setIsOpen(false), []);

  const confirm = useCallback(() => {
    setIsOpen(false);
    onConfirm();
  }, [onConfirm]);

  return (
    <>
      <Button variant="danger" onClick={() => setIsOpen(true)}>
        Удалить проект
      </Button>

      <Modal open={isOpen} onClose={close} aria-labelledby="delete-project-title">
        <Modal.Header id="delete-project-title">Удалить проект?</Modal.Header>

        <Modal.Body>
          <Stack direction="column" gap="var(--jx-space-2)">
            <Text style={{ color: 'var(--jx-color-text-secondary)' }}>
              {projectName
                ? `Проект «${projectName}» и все его данные будут удалены безвозвратно.`
                : 'Проект и все его данные будут удалены безвозвратно.'}
            </Text>
            <Text style={{ color: 'var(--jx-color-text-secondary)' }}>
              Это действие необратимо — отменить его не получится.
            </Text>
          </Stack>
        </Modal.Body>

        <Modal.Footer>
          <Stack direction="row" gap="var(--jx-space-2)" justify="flex-end">
            <Button variant="secondary" onClick={close}>
              Отмена
            </Button>
            <Button variant="danger" onClick={confirm}>
              Удалить проект
            </Button>
          </Stack>
        </Modal.Footer>
      </Modal>
    </>
  );
}

